import { game } from "pocket";
import { Cargo, Command, DamageInput, DashInput, DashState, Progress, Vitals, Wallet } from "./components";
import { collect, countParcels } from "./collect";
import { moveCourier } from "./dash";
import { updateProgress } from "./progress";
import { applyDamage } from "./damage";

export default game({
    components: [Cargo, Command, DamageInput, DashInput, DashState, Progress, Vitals, Wallet],
    systems: [countParcels, moveCourier, collect, updateProgress, applyDamage],
});

import { system } from "pocket";

export const updateProgress = system({
    name: "update_progress", phase: "update", doc: "Persist and emit each objective and score milestone once.",
    queries: {
        couriers: { with: ["Wallet", "Progress"],
            fields: ["Wallet.collected", "Wallet.points", "Wallet.total", "Progress.completed", "Progress.milestone"] },
    },
    run(ctx, { couriers }) {
        const wallet = couriers.cols.Wallet;
        const progress = couriers.cols.Progress;
        couriers.each((r, e) => {
            if (wallet.total[r] > 0 && wallet.collected[r] >= wallet.total[r] && progress.completed[r] === 0) {
                progress.completed[r] = 1;
                ctx.emit("game.won", { collected: wallet.collected[r], points: wallet.points[r] }, { subject: e });
            }
            if (wallet.points[r] >= 10 && progress.milestone[r] === 0) {
                progress.milestone[r] = 1;
                ctx.emit("score.milestone", { points: wallet.points[r] }, { subject: e });
            }
        });
    },
});

import { system } from "pocket";

export const applyDamage = system({
    name: "apply_damage", phase: "update", doc: "Consume armored damage and emit defeat once.",
    queries: {
        couriers: { with: ["DamageInput", "Vitals"], fields: ["DamageInput.amount", "Vitals.health", "Vitals.armor", "Vitals.defeated"] },
    },
    run(ctx, { couriers }) {
        const input = couriers.cols.DamageInput;
        const vitals = couriers.cols.Vitals;
        couriers.each((r, e) => {
            const amount = input.amount[r];
            input.amount[r] = 0;
            if (amount === 0) return;
            const damage = Math.max(0, amount - vitals.armor[r]);
            vitals.health[r] = Math.max(0, vitals.health[r] - damage);
            if (vitals.health[r] === 0 && vitals.defeated[r] === 0) {
                vitals.defeated[r] = 1;
                ctx.emit("game.lost", { health: 0 }, { subject: e });
            }
        });
    },
});

import { system } from "pocket";

export const moveCourier = system({
    name: "move_courier", phase: "update", doc: "Move by clamped intent, with a four-times dash and five-tick cooldown.",
    queries: {
        couriers: { with: ["DashInput", "DashState", "Transform"],
            fields: ["DashInput.dx", "DashInput.dz", "DashInput.request", "DashState.ready_at", "Transform.position"] },
    },
    run(ctx, { couriers }) {
        const input = couriers.cols.DashInput;
        const state = couriers.cols.DashState;
        const pos = couriers.cols.Transform.position;
        couriers.each((r, e) => {
            let multiplier = 1;
            if (input.request[r] === 1 && ctx.tick >= state.ready_at[r]) {
                multiplier = 4;
                state.ready_at[r] = ctx.tick + 5;
                ctx.emit("courier.dashed", { ready_at: state.ready_at[r] }, { subject: e });
            }
            input.request[r] = 0;
            pos.x[r] = pos.x[r] + Math.min(1, Math.max(-1, input.dx[r])) * multiplier;
            pos.z[r] = pos.z[r] + Math.min(1, Math.max(-1, input.dz[r])) * multiplier;
        });
    },
});

