import { system } from "pocket";

export const moveCourier = system({
    name: "move_courier", phase: "update", doc: "Move by clamped intent, with a four-times dash and five-tick cooldown.",
    queries: {
        couriers: { with: ["DashInput", "DashState", "Transform"],
            fields: ["DashInput.dx", "DashInput.dz", "DashInput.request", "DashState.ready_at", "Transform.position"] },
    },
    run(ctx, { couriers }) {
        const input = couriers.cols.DashInput;
        const state = couriers.cols.DashState;
        const pos = couriers.cols.Transform.position;
        couriers.each((r, e) => {
            // Every request is consumed, whether or not the dash is off cooldown.
            const requested = input.request[r] !== 0;
            input.request[r] = 0;

            let multiplier = 1;
            if (requested && ctx.tick >= state.ready_at[r]) {
                multiplier = 4;
                const ready_at = ctx.tick + 5;
                state.ready_at[r] = ready_at;
                ctx.emit("courier.dashed", { ready_at }, { subject: e });
            }

            const dx = Math.min(1, Math.max(-1, input.dx[r]));
            const dz = Math.min(1, Math.max(-1, input.dz[r]));
            pos.x[r] = pos.x[r] + dx * multiplier;
            pos.z[r] = pos.z[r] + dz * multiplier;
        });
    },
});

