import { system } from "pocket";

export const applyDamage = system({
    name: "apply_damage", phase: "update", doc: "Consume armored damage and emit defeat once.",
    queries: {
        couriers: { with: ["DamageInput", "Vitals"], fields: ["DamageInput.amount", "Vitals.health", "Vitals.armor", "Vitals.defeated"] },
    },
    run(ctx, { couriers }) {
        const input = couriers.cols.DamageInput;
        const vitals = couriers.cols.Vitals;
        couriers.each((r, e) => {
            const amount = input.amount[r];
            // Consume the queued intent on every tick, whatever it holds.
            input.amount[r] = 0;
            // Zero input does nothing: no damage, no defeat transition.
            if (amount === 0) return;
            // Armor absorbs each hit; it can never add health back.
            const absorbed = amount - vitals.armor[r];
            const damage = absorbed > 0 ? absorbed : 0;
            const health = vitals.health[r] - damage;
            vitals.health[r] = health > 0 ? health : 0;
            // A hit that leaves health at zero defeats the courier exactly once.
            if (vitals.health[r] === 0 && vitals.defeated[r] === 0) {
                vitals.defeated[r] = 1;
                ctx.emit("game.lost", { health: 0 }, { subject: e });
            }
        });
    },
});

