import { system } from "pocket";

export const applyDamage = system({
    name: "apply_damage", phase: "update", doc: "Consume armored damage and emit defeat once.",
    queries: {
        couriers: { with: ["DamageInput", "Vitals"], fields: ["DamageInput.amount", "Vitals.health", "Vitals.armor", "Vitals.defeated"] },
    },
    run(ctx, { couriers }) {
        const input = couriers.cols.DamageInput;
        const vitals = couriers.cols.Vitals;
        couriers.each((r, e) => {
            const amount = input.amount[r];
            // Consume the queued intention on this tick, whatever the outcome.
            input.amount[r] = 0;
            // Zero input does nothing at all.
            if (amount === 0) return;
            // Armor shaves the hit; a hit it fully absorbs deals nothing and never heals.
            const damage = Math.max(0, amount - vitals.armor[r]);
            const health = Math.max(0, vitals.health[r] - damage);
            vitals.health[r] = health;
            // A hit that leaves health at zero defeats once; the flag persists in the component.
            if (health === 0 && vitals.defeated[r] === 0) {
                vitals.defeated[r] = 1;
                ctx.emit("game.lost", { health: 0 }, { subject: e });
            }
        });
    },
});

